class Game:
    def __init__(self, players):
        self.players = [Player(name) for name in players]
        self.deck = Deck()
        self.deck.shuffle()

    def distribute_cards(self):
        while self.deck.cards:
            for player in self.players:
                card = self.deck.draw()
                if card is not None:
