    def cosine_similarity(self, other) -> float:
        pass

class MyVector(Vector):
    def manhattan_distance(self, other) -> float:
        if len(self.vals) != len(other.vals):
            raise ValueError("Vectors must have the same length")
        return sum(abs(x - y) for x, y in zip(self.vals, other.vals))

    def cosine_similarity(self, other) -> float:
        if len(self.vals) != len(other.vals):
            raise ValueError("Vectors must have the same length")

        dot_product = sum(x * y for x, y in zip(self.vals, other.vals))
        magnitude_self = math.sqrt(sum(x ** 2 for x in self.vals))
        magnitude_other = math.sqrt(sum(y ** 2 for y in other.vals))

        if magnitude_self == 0 or magnitude_other == 0:
            raise ValueError("One of the vectors has magnitude zero")

        return dot_product / (magnitude_self * magnitude_other)

